#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1000000007;

ll N, K;

struct Matrix {
    vector<vector<ll>> a;
    Matrix() {}
    Matrix(int n) : a(n, vector<ll>(n, 0)) {}
    Matrix(int n, int m) : a(n, vector<ll>(m, 0)) {}
    int rows() const { return a.size(); }
    int cols() const { return a[0].size(); }
    static Matrix I(int n) {
        Matrix r(n);
        for (int i = 0; i < n; ++i) r.a[i][i] = 1;
        return r;
    }
    Matrix operator*(const Matrix& b) const {
        Matrix c(rows(), b.cols());
        for (int i = 0; i < rows(); ++i)
            for (int j = 0; j < b.cols(); ++j)
                for (int k = 0; k < cols(); ++k)
                    c.a[i][j] = (c.a[i][j] + a[i][k] * b.a[k][j]) % MOD;
        return c;
    }
    Matrix& operator*= (const Matrix& b) { *this = *this * b; return *this; }
    Matrix operator+(const Matrix& b) const {
        Matrix c(rows(), cols());
        for (int i = 0; i < rows(); ++i)
            for (int j = 0; j < cols(); ++j)
                c.a[i][j] = (a[i][j] + b.a[i][j]) % MOD;
        return c;
    }
    Matrix operator-(const Matrix& b) const {
        Matrix c(rows(), cols());
        for (int i = 0; i < rows(); ++i)
            for (int j = 0; j < cols(); ++j)
                c.a[i][j] = (a[i][j] - b.a[i][j] + MOD) % MOD;
        return c;
    }
    Matrix operator^(ll e) const {
        Matrix base = *this;
        Matrix res = I(rows());
        while (e) {
            if (e & 1) res = res * base;
            base = base * base;
            e >>= 1;
        }
        return res;
    }
    void rot() {
        int n = rows();
        Matrix tmp(n);
        for (int i = 0; i < K; ++i) {
            for (int j = 0; j < K; ++j)
                tmp.a[i][j] = a[(i + K - 1) % K][(j + K - 1) % K];
            tmp.a[i][K] = a[(i + K - 1) % K][K];
            tmp.a[K][i] = a[K][(i + K - 1) % K];
        }
        tmp.a[K][K] = a[K][K];
        a = tmp.a;
    }
};

Matrix mat[70][35];

ll fastPow(ll a, ll b) {
    ll r = 1;
    while (b) {
        if (b & 1) r *= a;
        a *= a;
        b >>= 1;
    }
    return r;
}

int main() {
    cin >> N >> K;
    int maxExp = 0;
    ll copyN = N;
    while (copyN >= K) {
        maxExp++;
        copyN /= K;
    }
    mat[0][0] = Matrix::I(K + 1);
    for (int i = 1; i <= K; ++i) mat[0][0].a[0][i] = 1;
    for (int i = 1; i < K; ++i) {
        mat[0][i] = mat[0][i - 1];
        mat[0][i].rot();
    }
    for (int e = 1; e <= maxExp; ++e) {
        mat[e][0] = mat[e - 1][0];
        for (int i = 1; i < K; ++i)
            mat[e][0] = mat[e - 1][i] * mat[e][0];
        for (int i = 1; i < K; ++i) {
            mat[e][i] = mat[e][i - 1];
            mat[e][i].rot();
        }
    }
    Matrix ans(K + 1, 1);
    ans.a[K][0] = 1;
    int used = 0;
    while (maxExp >= 0) {
        while (true) {
            ll p = fastPow(K, maxExp);
            if (p <= N) {
                N -= p;
                ans = mat[maxExp][used] * ans;
                used = (used + 1) % K;
            } else break;
        }
        maxExp--;
    }
    ll sum = 0;
    for (int i = 0; i <= K; ++i) sum = (sum + ans.a[i][0]) % MOD;
    cout << sum << '\n';
}
